from flask import Flask, render_template, request, jsonifyimport osimport smtplibfrom email.mime.text import MIMETextapp = Flask(__name__)@app.route("/")def index():    return render_template("index.html")@app.route("/test-json")def test_json():    return jsonify({"status": "ok", "message": "Flask fonctionne bien"})@app.route('/contact-sponsor', methods=['POST'])def contact_sponsor():    choix = request.form.get('choix')    email = request.form.get('email')    if not choix or not email:        return jsonify({            "status": "error",            "message": "Données manquantes"        }), 400    email_user = os.environ.get("EMAIL_USER")    email_pass = os.environ.get("EMAIL_PASS")    if not email_user or not email_pass:        return jsonify({            "status": "error",            "message": "Variables EMAIL_USER ou EMAIL_PASS manquantes sur Render"        }), 500    message = f"""Nouvelle demande sponsor :Choix : {choix}Email : {email}"""    msg = MIMEText(message)    msg["Subject"] = "Nouveau contact sponsor"    msg["From"] = email_user    msg["To"] = email_user    msg["Reply-To"] = email    try:        with smtplib.SMTP_SSL("smtp.gmail.com", 465) as server:            server.login(email_user, email_pass)            server.send_message(msg)        return jsonify({"status": "ok"})    except Exception as e:        print("ERREUR EMAIL :", e)        return jsonify({            "status": "error",            "message": str(e)        }), 500@app.route("/equipage")def equipage():    return render_template("equipe.html")@app.route("/sponsor")def sponsor():    return render_template("sponsor.html")@app.route("/concept")def concept():    return render_template("concept.html")@app.route("/pourquoi")def pourquoi():    return render_template("pourquoi.html")@app.route("/financer")def financer():    return render_template("financer.html")if __name__ == "__main__":    app.run(debug=True)    